/**
 * Get all formula cards for a specific class (1-10)
 */
export const getClassFormulaCards = (classId) => {
  const cNum = typeof classId === 'string' ? parseInt(classId.replace(/\D/g, ''), 10) : classId;
  return Object.values(classFormulaCards).filter(fc => fc.classId === cNum);
};

/**
 * Get formula card for a specific topic ID
 */
export const getFormulaCardsForTopic = (topicId) => {
  if (!topicId) return [];
  const card = classFormulaCards[topicId];
  return card ? [card] : [];
};

/**
 * Get all formula cards belonging to a chapter / theme
 */
export const getFormulaCardsForChapter = (chapterId, classId) => {
  const cNum = typeof classId === 'string' ? parseInt(classId.replace(/\D/g, ''), 10) : classId;
  return Object.values(classFormulaCards).filter(fc => {
    const matchesClass = cNum ? fc.classId === cNum : true;
    const matchesChap = chapterId ? fc.chapterId === chapterId || fc.themeId === chapterId || fc.topicId.startsWith(chapterId.replace('chap_', 'les_')) : true;
    return matchesClass && matchesChap;
  });
};
